import{_ as e,a as d,o as a,a6 as o}from"./chunks/framework.CJDy2q7X.js";const p=JSON.parse('{"title":"Catalog Categories — Datagrid Listing","description":"","frontmatter":{"outline":false,"apiType":"rest","examples":[{"id":"admin-catalog-categories-list","title":"List Catalog Categories (Datagrid)","description":"Paginated, filterable, sortable category list mirroring the Bagisto admin Catalog → Categories datagrid. Returns the standard `{ data, meta }` envelope.","query":"curl -X GET \\"https://your-domain.com/api/admin/catalog/categories?per_page=10&page=1&status=1&sort=name-asc\\" \\\\\\n  -H \\"Authorization: Bearer <token>\\" \\\\\\n  -H \\"Accept: application/json\\"\\n","variables":"per_page=10&page=1&status=1&sort=name-asc\\n","response":"{\\n  \\"data\\": [\\n    {\\n      \\"id\\": 7,\\n      \\"position\\": 1,\\n      \\"status\\": 1,\\n      \\"parentId\\": 1,\\n      \\"displayMode\\": \\"products_and_description\\",\\n      \\"logoUrl\\": null,\\n      \\"bannerUrl\\": null,\\n      \\"name\\": \\"Apparel\\",\\n      \\"slug\\": \\"apparel\\",\\n      \\"description\\": \\"Men\'s and women\'s apparel\\",\\n      \\"locale\\": \\"en\\",\\n      \\"createdAt\\": \\"2026-01-12T08:15:00+00:00\\",\\n      \\"updatedAt\\": \\"2026-04-30T14:20:09+00:00\\",\\n      \\"translations\\": null,\\n      \\"filterableAttributeIds\\": null\\n    }\\n  ],\\n  \\"meta\\": {\\n    \\"currentPage\\": 1,\\n    \\"perPage\\": 10,\\n    \\"lastPage\\": 5,\\n    \\"total\\": 47,\\n    \\"from\\": 1,\\n    \\"to\\": 10\\n  }\\n}\\n","commonErrors":[{"error":"Unauthorized (401)","cause":"Missing, invalid, expired, or revoked admin Bearer token","solution":"Send a valid admin Bearer token (Integration token) in the Authorization header. See the Authentication page."}]}]},"headers":[],"relativePath":"api/rest-api/admin/catalog/categories/categories-listing.md","filePath":"api/rest-api/admin/catalog/categories/categories-listing.md","lastUpdated":1787290888000}'),r={name:"api/rest-api/admin/catalog/categories/categories-listing.md"};function i(n,t,s,c,l,g){return a(),d("div",null,t[0]||(t[0]=[o('<h1 id="catalog-categories-—-datagrid-listing" tabindex="-1">Catalog Categories — Datagrid Listing <a class="header-anchor" href="#catalog-categories-—-datagrid-listing" aria-label="Permalink to &quot;Catalog Categories — Datagrid Listing&quot;">​</a></h1><p>Paginated, filterable, and sortable category list that mirrors the Bagisto admin <strong>Catalog → Categories</strong> datagrid 1:1. This is the authoritative category-management listing for the admin API — same columns, same filters, and the same sort options used by the datagrid.</p><p>For the flat-list versus tree shapes, hierarchy and move semantics, and display modes, see the <a href="/api/rest-api/admin/catalog/categories/">Categories overview</a>.</p><p>This endpoint returns a <strong>flat, paginated list</strong>, which is what a datagrid needs. For the nested hierarchy behind a tree picker use <a href="/api/rest-api/admin/catalog/categories/categories-tree.html"><code>GET /api/admin/catalog/categories/tree</code></a> instead.</p><h2 id="endpoint" tabindex="-1">Endpoint <a class="header-anchor" href="#endpoint" aria-label="Permalink to &quot;Endpoint&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Endpoint</th><th>Method</th><th>Authentication</th></tr></thead><tbody><tr><td><code>/api/admin/catalog/categories</code></td><td>GET</td><td>Admin Bearer token</td></tr></tbody></table><h2 id="query-parameters" tabindex="-1">Query Parameters <a class="header-anchor" href="#query-parameters" aria-label="Permalink to &quot;Query Parameters&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Description</th><th>Example</th></tr></thead><tbody><tr><td><code>page</code></td><td>integer</td><td>Page number (1-based, default <code>1</code>)</td><td><code>1</code></td></tr><tr><td><code>per_page</code></td><td>integer</td><td>Items per page (default <code>10</code>, max <code>50</code>)</td><td><code>10</code></td></tr><tr><td><code>category_id</code></td><td>string</td><td>Filter by category ID — single integer or comma-separated list (e.g. <code>&quot;12&quot;</code> or <code>&quot;12,18&quot;</code>)</td><td><code>7</code></td></tr><tr><td><code>name</code></td><td>string</td><td>Partial category name match (SQL <code>LIKE %value%</code>)</td><td><code>Apparel</code></td></tr><tr><td><code>position</code></td><td>integer</td><td>Exact position filter</td><td><code>1</code></td></tr><tr><td><code>status</code></td><td>integer</td><td>Filter by status: <code>0</code> = disabled, <code>1</code> = enabled</td><td><code>1</code></td></tr><tr><td><code>parent_id</code></td><td>integer</td><td>Filter by parent category ID</td><td><code>1</code></td></tr><tr><td><code>locale</code></td><td>string</td><td>Locale code for translation resolution (default: app locale)</td><td><code>en</code></td></tr><tr><td><code>sort</code></td><td>string</td><td>Column to sort by (see Sorting section below)</td><td><code>id</code></td></tr><tr><td><code>order</code></td><td>string</td><td>Sort direction: <code>asc</code> or <code>desc</code> (default <code>desc</code>)</td><td><code>desc</code></td></tr></tbody></table><h2 id="response-shape" tabindex="-1">Response Shape <a class="header-anchor" href="#response-shape" aria-label="Permalink to &quot;Response Shape&quot;">​</a></h2><p>Responses use the standard admin <code>{ data, meta }</code> envelope.</p><h3 id="meta-object" tabindex="-1"><code>meta</code> object <a class="header-anchor" href="#meta-object" aria-label="Permalink to &quot;`meta` object&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>currentPage</code></td><td>integer</td><td>Current page number (1-based)</td></tr><tr><td><code>perPage</code></td><td>integer</td><td>Number of items on this page</td></tr><tr><td><code>lastPage</code></td><td>integer</td><td>Total number of pages</td></tr><tr><td><code>total</code></td><td>integer</td><td>Total matching categories</td></tr><tr><td><code>from</code></td><td>integer</td><td>1-based index of the first item on this page</td></tr><tr><td><code>to</code></td><td>integer</td><td>1-based index of the last item on this page</td></tr></tbody></table><h3 id="row-fields-data" tabindex="-1">Row fields (<code>data[]</code>) <a class="header-anchor" href="#row-fields-data" aria-label="Permalink to &quot;Row fields (`data[]`)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>integer</td><td>Category ID</td></tr><tr><td><code>position</code></td><td>integer</td><td>Display order position</td></tr><tr><td><code>status</code></td><td>integer</td><td><code>1</code> = enabled, <code>0</code> = disabled</td></tr><tr><td><code>parentId</code></td><td>integer|null</td><td>ID of the parent category; <code>null</code> for root nodes</td></tr><tr><td><code>displayMode</code></td><td>string|null</td><td>How the category page is displayed (e.g. <code>products_and_description</code>)</td></tr><tr><td><code>logoUrl</code></td><td>string|null</td><td>Storage URL for the category logo; <code>null</code> if not set</td></tr><tr><td><code>bannerUrl</code></td><td>string|null</td><td>Storage URL for the category banner; <code>null</code> if not set</td></tr><tr><td><code>name</code></td><td>string|null</td><td>Category name resolved via <code>locale</code></td></tr><tr><td><code>slug</code></td><td>string|null</td><td>URL slug (e.g. <code>apparel</code>)</td></tr><tr><td><code>description</code></td><td>string|null</td><td>Category description in the resolved locale</td></tr><tr><td><code>locale</code></td><td>string|null</td><td>Locale code used for resolution</td></tr><tr><td><code>createdAt</code></td><td>string|null</td><td>ISO 8601 creation timestamp</td></tr><tr><td><code>updatedAt</code></td><td>string|null</td><td>ISO 8601 last-update timestamp</td></tr><tr><td><code>translations</code></td><td>null</td><td>Always <code>null</code> in list responses — full translations are available via the detail endpoint <code>GET /api/admin/catalog/categories/{id}</code></td></tr><tr><td><code>filterableAttributeIds</code></td><td>null</td><td>Always <code>null</code> in list responses — available via the detail endpoint</td></tr></tbody></table><h2 id="sorting" tabindex="-1">Sorting <a class="header-anchor" href="#sorting" aria-label="Permalink to &quot;Sorting&quot;">​</a></h2><p>Two forms are accepted — choose whichever suits your client:</p><table tabindex="0"><thead><tr><th>Form</th><th>Example</th></tr></thead><tbody><tr><td>Compound <code>sort</code> param</td><td><code>?sort=name-asc</code></td></tr><tr><td>Separate <code>sort</code> + <code>order</code> params</td><td><code>?sort=name&amp;order=asc</code></td></tr></tbody></table><p>When both <code>order</code> and a compound <code>sort</code> value are present, the explicit <code>order</code> param takes precedence.</p><p><strong>Sortable columns:</strong></p><table tabindex="0"><thead><tr><th><code>sort</code> value</th><th>Sorts by</th></tr></thead><tbody><tr><td><code>id</code></td><td>Category ID (default)</td></tr><tr><td><code>name</code></td><td>Category name</td></tr><tr><td><code>position</code></td><td>Display order position</td></tr><tr><td><code>status</code></td><td>Enabled/disabled status</td></tr></tbody></table><h2 id="pagination" tabindex="-1">Pagination <a class="header-anchor" href="#pagination" aria-label="Permalink to &quot;Pagination&quot;">​</a></h2><ul><li>Default page size: <strong>10</strong> items</li><li>Maximum page size: <strong>50</strong> items</li><li>Use <code>?page=N</code> for page navigation and <code>?per_page=N</code> to control page size</li></ul><h2 id="errors" tabindex="-1">Errors <a class="header-anchor" href="#errors" aria-label="Permalink to &quot;Errors&quot;">​</a></h2><table tabindex="0"><thead><tr><th>HTTP</th><th>Detail</th></tr></thead><tbody><tr><td><code>401</code></td><td><code>Unauthenticated.</code></td></tr></tbody></table><p>The listing never rejects a bad filter. An unknown parameter is ignored, and an out-of-range <code>status</code> is dropped rather than applied — both return the full unfiltered list, so a wrong filter looks like a successful query. <code>?per_page=999</code> is clamped to <code>50</code>, and <code>?per_page=0</code> falls back to <code>10</code>.</p><h2 id="fields-that-stay-null-on-the-listing" tabindex="-1">Fields That Stay Null on the Listing <a class="header-anchor" href="#fields-that-stay-null-on-the-listing" aria-label="Permalink to &quot;Fields That Stay Null on the Listing&quot;">​</a></h2><p><code>translations</code> and <code>filterableAttributeIds</code> are present on every row but always <code>null</code>. Both resolve only on <a href="/api/rest-api/admin/catalog/categories/categories-detail.html"><code>GET /api/admin/catalog/categories/{id}</code></a>, which returns all locale translations in one call.</p><h2 id="behaviour-worth-knowing" tabindex="-1">Behaviour Worth Knowing <a class="header-anchor" href="#behaviour-worth-knowing" aria-label="Permalink to &quot;Behaviour Worth Knowing&quot;">​</a></h2><ul><li><strong>No implicit status filter.</strong> Every status is returned so an admin can find a disabled category. Pass <code>?status=1</code> for enabled only.</li><li><strong><code>parent_id</code> returns direct children only</strong>, not the whole subtree. For a full branch use the tree endpoint with <code>?rootId=&lt;id&gt;</code>.</li><li><strong><code>name</code>, <code>slug</code>, and <code>description</code> are per-locale.</strong> A category with no translation in the requested locale returns <code>null</code> for all three — the row still appears, so an empty name is not a missing category.</li><li><strong>Scalars are real types.</strong> <code>status</code>, <code>position</code>, and <code>parentId</code> are integers, and timestamps are ISO 8601 with offset — note the product listing uses <code>2026-04-19 11:56:43</code> instead, so the two are not interchangeable.</li></ul>',29)]))}const u=e(r,[["render",i]]);export{p as __pageData,u as default};
